 static void actionBarrier(ClientSession pc,GameHub hub,ClassicWorldMonsterPopulation pop,CaptureLog capture)throws Exception{
  RangedDamageRegression.equip(pc,4,12);for(int stage=0;stage<3;stage++){
   factor(pc,2);var a=wounded(pop,4550+stage);long id=a.objectId();var t=timed(pop,id);if(stage!=0)pop.strikerGale(4,id,System.nanoTime(),60);long offset=Files.size(capture.path());var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var error=new AtomicReference<Throwable>();var once=new AtomicBoolean();Socket saved=(Socket)get(pc,"socket");Socket watched=new Socket(){public OutputStream getOutputStream()throws IOException{return new FilterOutputStream(saved.getOutputStream()){public void write(byte[] bytes,int off,int len)throws IOException{if(Thread.currentThread().getName().equals("world-physical-action")&&CombatPoisonLifecycle.monsterDamage(t,false)!=null&&once.compareAndSet(false,true)){check(!Thread.holdsLock(t)&&!Thread.holdsLock(pop)&&!Thread.holdsLock(hub),"native action socket outside state monitors");entered.countDown();try{if(!release.await(4,TimeUnit.SECONDS))throw new AssertionError("action barrier timeout");}catch(InterruptedException e){throw new AssertionError(e);}}out.write(bytes,off,len);}public void write(int b)throws IOException{out.write(b);}};}};
   set(pc,"socket",watched);var worker=new Thread(()->{try{packet(pc,a);}catch(Throwable e){error.set(e);entered.countDown();}},"world-physical-action");worker.start();try{check(entered.await(3,TimeUnit.SECONDS)&&error.get()==null,"actual S_ATTACK reaches socket before commit: "+error.get());check(hp(pop,id)==40000,"action publication precedes accepted HP");if(stage==0)pop.strikerGale(4,id,System.nanoTime(),60);else if(stage==1)pop.strikerGale(4,id,1,1);else t.clear();}finally{release.countDown();worker.join(4000);set(pc,"socket",saved);watched.close();}check(!worker.isAlive()&&error.get()==null,"native action completes without deadlock: "+error.get());drain(hub);int raw=shown(capture,offset,pc,id);check(hp(pop,id)==(stage==2?40000:40000-raw*(stage==0?2:1)),"post-action Striker lookup and pre-action actor epoch guard stage="+stage);discard(pop,id);
  }
 }
