  var root=Path.of(args[1]);Files.createDirectories(root);var state=new GameStateStore(root.resolve("unused"),false,true);AccountRepository memory=new MemoryAccountRepository("fixture","fixture","",0,1,40,52);AccountRepository accounts=(AccountRepository)java.lang.reflect.Proxy.newProxyInstance(WorldPhysicalCommitRegression.class.getClassLoader(),new Class[]{AccountRepository.class},(p,m,a)->{if(m.getName().equals("repositoryForClassicSource"))return p;if(m.getName().equals("npcPhysicalStats"))return copy(SourceNpcPhysicalStats.memoryFixture((int)a[0]),Map.of("armorClass",10,"damageReduction",0,"hard",false,"magicResistance",0,"boss",false,"undead",0));try{return m.invoke(memory,a);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});
